Scene3Update:              ; B goes back
    ldh a, [hPadNew]
    and PADF_B
    ret z
    ld a, SFX_MENU_BACK
    call PlaySfx
    ld a, 0
    jp StartTransition

Scene4Update:              ; press-start screen: wait for Start or A
    ldh a, [hPadNew]
    and PADF_A | PADF_START
    jr nz, .press
    ldh a, [hFrame]         ; the prompt blinks every 32 frames
    and 31
    ret nz
    ldh a, [hPromptHidden]
    xor 1
    ldh [hPromptHidden], a
    ld hl, Scene4PromptShown
    jr z, .queue
    ld hl, Scene4PromptHidden
.queue:
    QUEUE_PATCH Scene4PromptPatch
    ret
.press:
    ld a, SFX_PRESS_START
    call PlaySfx
    ld a, 1
    ldh [hCounter], a
    ld a, 1
    ldh [hTimer], a
    SET_UPDATE Scene4Press
    ldh a, [hPromptHidden]  ; make sure the prompt is showing
    and a
    ret z
    xor a
    ldh [hPromptHidden], a
    ld hl, Scene4PromptShown
    QUEUE_PATCH Scene4PromptPatch
    ret

Scene4Press:              ; flip the flash area, then go
    ld hl, hTimer
    dec [hl]
    ret nz
    ld [hl], BLINK_FRAMES
    ld hl, hCounter
    ld a, [hl]
    and a
    jr z, .go
    dec [hl]
    ret
.go:
    ld a, 1
    jp StartTransition

